public static String applyRelativePath(String path, String relativePath) {
    StringBuilder sb = new StringBuilder();
    // Split the path by the "/" separator
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Skip the first segment of the path if it is empty
    int i = 0;
    if (pathSegments[0].isEmpty()) {
        i++;
    }

    // Iterate through the relative path segments
    for (int j = 0; j < relativePathSegments.length; j++) {
        String segment = relativePathSegments[j];

        // If the segment is "..", then go back one segment in the path
        if (segment.equals("..")) {
            i--;
        } else {
            // Add the segment to the path
            sb.append(pathSegments[i++]);
            sb.append("/");
        }
    }

    // Add any remaining segments to the path
    while (i < pathSegments.length) {
        sb.append(pathSegments[i++]);
        sb.append("/");
    }

    // Remove the trailing "/" from the path
    if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '/') {
        sb.deleteCharAt(sb.length() - 1);
    }

    return sb.toString();
}

